style.css:
/* Discord – Sweet Letters */

:root {
  --my-font: "Arial Rounded MT Bold", "Trebuchet MS", sans-serif;
}

/* make Discord text cute and rounded */
body,
button,
input,
textarea,
[class*="message"],
[class*="username"],
[class*="channelName"],
[class*="markup"],
[class*="placeholder"] {
  font-family: var(--my-font) !important;
}
